 "content": "def transform(grid):
    """Extend center row/column rays from each solid 3x3 color block."""
    h, w = len(grid), len(grid[0])
    blocks = []
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[i][j] == color
                             for i in range(r, r + 3)
                             for j in range(c, c + 3)):
                blocks.append((r + 1, c + 1, color))

    # Preserve original objects. Extend only through empty cells; where rays
    # from differently colored blocks intersect, the crossing remains empty.
    rays = {}
    for r, c, color in blocks:
        for j in range(w):
            rays.setdefault((r, j), set()).add(color)
        for i in range(h):
            rays.setdefault((i, c), set()).add(color)

    result = [row[:] for row in grid]
    for (r, c), colors in rays.items():
        if grid[r][c] == 0 and len(colors) == 1:
            result[r][c] = next(iter(colors))
    return result
